async def act(page):
    """
    From the current 'Create Product Settings' page, click the Continue button to open
    the new product form. This action is expected to navigate away, so it is the last
    action performed in this function.
    """
    # Helper to try clicking a locator if present
    async def try_click(locator):
        try:
            if await locator.count() > 0:
                await locator.first.click()
                return True
        except Exception:
            return False
        return False

    # Attempt to close any obvious blocking popup first (non-navigating action).
    for close_name in ["Close", "close", "Dismiss", "×", "✖", "Close (Esc)"]:
        try:
            btn = page.get_by_role("button", name=close_name)
            if await btn.count() > 0:
                # click and continue (do not assume navigation)
                await btn.first.click()
                break
        except Exception:
            pass

    # Click the Continue button using the full table -> row -> button path from the accessibility tree
    try:
        continue_btn = page.get_by_role("table").get_by_role("row", name="Continue").get_by_role("button", name="Continue")
        if await continue_btn.count() > 0:
            await continue_btn.first.click()
            return
    except Exception:
        pass

    # Fallback: top-level Continue button
    try:
        fallback = page.get_by_role("button", name="Continue")
        if await fallback.count() > 0:
            await fallback.first.click()
            return
    except Exception:
        pass

    # If we couldn't find the Continue button, raise to surface the issue
    raise Exception("Unable to find Continue button using accessibility role selectors.")

